import json
from pathlib import Path
cases=[]
def add(item, phrases, expectation):
    for text in phrases:
        cases.append(dict(id=f'{item}-{sum(c["item"]==item for c in cases)+1}',item=item,text=text,expected=json.loads(json.dumps(expectation))))
def direct(item, phrases, action):
    add(item,phrases,dict(route='deterministic',actions=[action]))
def mapcase(item, phrases, action, **args): direct(item,phrases,dict(kind='map',action=action,args=args))
def ui(item, phrases, **command): direct(item,phrases,dict(kind='ui',command=command))
def resource(item, phrases, action, target='', **payload): direct(item,phrases,dict(kind='resource',action=action,target=target,payload=payload))
def intent(item, phrases, command, target, **payload): direct(item,phrases,dict(kind='intent',intent=command,target=target,payload=payload))
